22	export function build(options: BuildOptions): BuildResult {
23	  const { contentDir, outputDir } = options;
24	  const templatesDir = options.templatesDir ?? path.resolve(process.cwd(), 'templates');
25	
26	  if (!fs.existsSync(contentDir) || !fs.statSync(contentDir).isDirectory()) {
27	    throw new Error(`Content directory not found: ${contentDir}`);
28	  }
29	
30	  const engine = new TemplateEngine(templatesDir);
31	
32	  const markdownFiles = findMarkdownFiles(contentDir);
33	  const pages = markdownFiles.map((filePath) => buildPage(filePath, contentDir));
34	  pages.sort(comparePages);
35	
36	  fs.mkdirSync(outputDir, { recursive: true });
37	
38	  for (const page of pages) {
39	    const outPath = path.join(outputDir, page.outputFile);
40	    fs.mkdirSync(path.dirname(outPath), { recursive: true });
41	    const html = engine.render(page.layout, {
42	      title: page.title,
43	      date: page.date,
44	      tags: page.tags,
45	      body: page.html,
46	    });
47	    fs.writeFileSync(outPath, html, 'utf8');
48	  }
49	
50	  const indexLayout = engine.hasLayout(INDEX_LAYOUT_NAME) ? INDEX_LAYOUT_NAME : undefined;
51	  const indexHtml = engine.render(indexLayout, {
52	    title: 'All Pages',
53	    tags: [],
54	    body: renderIndexBodyHtml(pages),
55	  });
56	  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml, 'utf8');
57	
58	  return { pages, outputDir };
59	}
