68	function findMarkdownFiles(dir: string): string[] {
69	  const entries = fs.readdirSync(dir, { withFileTypes: true });
70	  const files: string[] = [];
71	
72	  for (const entry of entries) {
73	    const fullPath = path.join(dir, entry.name);
74	    if (entry.isDirectory()) {
75	      files.push(...findMarkdownFiles(fullPath));
76	    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
77	      files.push(fullPath);
78	    }
79	  }
80	
81	  return files;
82	}
