84	function buildPage(filePath: string, contentDir: string): Page {
85	  const raw = fs.readFileSync(filePath, 'utf8');
86	  const { data, content } = parseFrontmatter(raw);
87	  const html = renderMarkdown(content);
88	
89	  const relativePath = path.relative(contentDir, filePath);
90	  const slug = slugify(relativePath);
91	  const title = typeof data.title === 'string' && data.title.trim() ? data.title : slug;
92	  const date = typeof data.date === 'string' && data.date.trim() ? data.date : undefined;
93	  const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
94	  const layout = typeof data.layout === 'string' && data.layout.trim() ? data.layout.trim() : undefined;
95	
96	  return {
97	    slug,
98	    title,
99	    date,
100	    tags,
101	    html,
102	    sourcePath: relativePath,
103	    outputFile: `${slug}.html`,
104	    layout,
105	  };
106	}
