108	function slugify(relativePath: string): string {
109	  const withoutExt = relativePath.replace(/\.md$/i, '');
110	  const slug = withoutExt
111	    .split(path.sep)
112	    .join('-')
113	    .toLowerCase()
114	    .replace(/[^a-z0-9-]+/g, '-')
115	    .replace(/-+/g, '-')
116	    .replace(/^-|-$/g, '');
117	
118	  // "index" is reserved for the generated listing page.
119	  if (!slug || slug === 'index') return slug === 'index' ? 'index-page' : 'page';
120	  return slug;
121	}
